package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"unicode"
)

type VuiNode struct {
	Type     string         `json:"type"`
	ID       string         `json:"id,omitempty"`
	Props    map[string]any `json:"props,omitempty"`
	Layout   *VuiLayoutDef  `json:"layout,omitempty"`
	Children []*VuiNode     `json:"children,omitempty"`
}

type VuiLayoutDef struct {
	Type    string `json:"type"`
	Spacing any    `json:"spacing,omitempty"`
	Margins []int  `json:"margins,omitempty"`
	Align   string `json:"align,omitempty"`
}

type VuiConnection struct {
	From    string `json:"from"`
	Signal  string `json:"signal"`
	Command any    `json:"command,omitempty"`
	Emit    bool   `json:"emit,omitempty"`
}

type VuiDocument struct {
	VuiVersion  int               `json:"vuiVersion"`
	Root        *VuiNode          `json:"root"`
	Connections []VuiConnection   `json:"connections,omitempty"`
	TabOrder    []string          `json:"tabOrder,omitempty"`
	Palette     map[string]string `json:"palette,omitempty"`
}

func exportFieldName(id string) string {
	if id == "" {
		return ""
	}
	runes := []rune(id)
	runes[0] = unicode.ToUpper(runes[0])
	return string(runes)
}

func goTypeName(nodeType string) string {
	switch nodeType {
	case "Dialog", "Window":
		return "*vtui.Window"
	case "Button":
		return "*vtui.Button"
	case "Edit":
		return "*vtui.Edit"
	case "MultiLineEdit":
		return "*vtui.MultiLineEdit"
	case "Checkbox":
		return "*vtui.Checkbox"
	case "RadioButton":
		return "*vtui.RadioButton"
	case "RadioGroup":
		return "*vtui.RadioGroup"
	case "CheckGroup":
		return "*vtui.CheckGroup"
	case "Label", "Text":
		return "*vtui.Text"
	case "ListBox":
		return "*vtui.ListBox"
	case "ComboBox":
		return "*vtui.ComboBox"
	case "Table":
		return "*vtui.Table"
	case "VMenu":
		return "*vtui.VMenu"
	case "MenuBar":
		return "*vtui.MenuBar"
	case "KeyBar":
		return "*vtui.KeyBar"
	case "StatusLine":
		return "*vtui.StatusLine"
	case "ProgressBar":
		return "*vtui.ProgressBar"
	case "Separator":
		return "*vtui.Separator"
	case "Spacer":
		return "*vtui.Spacer"
	case "GroupBox":
		return "*vtui.GroupBox"
	case "BorderedFrame":
		return "*vtui.BorderedFrame"
	case "Group":
		return "*vtui.Group"
	default:
		return "vtui.UIElement"
	}
}

func generateGoCode(doc *VuiDocument, srcFileName, pkgName string) string {
	var b strings.Builder
	b.WriteString(fmt.Sprintf("// Code generated by vuic from %s. DO NOT EDIT.\n", filepath.Base(srcFileName)))
	b.WriteString("// This generated code belongs to the author of the .vui file and is not subject to vtui framework license restrictions.\n\n")
	fmt.Fprintf(&b, "package %s\n\n", pkgName)
	b.WriteString("import (\n\t\"github.com/unxed/vtui\"\n)\n\n")

	rootName := exportFieldName(doc.Root.ID)
	if rootName == "" {
		rootName = "Root"
	}

	structName := fmt.Sprintf("Ui_%s", rootName)
	fmt.Fprintf(&b, "type %s struct {\n", structName)

	var namedNodes []struct {
		ID   string
		Type string
	}
	var collectNamed func(n *VuiNode)
	collectNamed = func(n *VuiNode) {
		if n == nil {
			return
		}
		if n.ID != "" {
			namedNodes = append(namedNodes, struct {
				ID   string
				Type string
			}{ID: n.ID, Type: n.Type})
		}
		for _, child := range n.Children {
			collectNamed(child)
		}
	}
	collectNamed(doc.Root)

	for _, nn := range namedNodes {
		fmt.Fprintf(&b, "\t%s %s\n", exportFieldName(nn.ID), goTypeName(nn.Type))
	}
	b.WriteString("}\n\n")

	funcName := fmt.Sprintf("Build%s", rootName)
	fmt.Fprintf(&b, "func %s() (*vtui.Window, *%s) {\n", funcName, structName)
	fmt.Fprintf(&b, "\tui := &%s{}\n\n", structName)

	b.WriteString("\tdoc := &vtui.VuiDocument{\n")
	data, _ := json.MarshalIndent(doc, "\t\t", "\t")
	b.WriteString("\t\t")
	b.WriteString(string(data))
	b.WriteString(",\n\t}\n\n")

	b.WriteString("\twin, err := vtui.LoadVuiDocument(doc)\n")
	b.WriteString("\tif err != nil {\n\t\tpanic(err)\n\t}\n\n")

	for _, nn := range namedNodes {
		fname := exportFieldName(nn.ID)
		gtype := goTypeName(nn.Type)
		fmt.Fprintf(&b, "\tif el, ok := vtui.FrameManager.Lookup(win.ID(), %q); ok {\n", nn.ID)
		fmt.Fprintf(&b, "\t\tif v, ok := el.(%s); ok {\n\t\t\tui.%s = v\n\t\t}\n\t}\n", gtype, fname)
	}

	b.WriteString("\n\treturn win, ui\n}\n")
	return b.String()
}

func main() {
	pkgFlag := flag.String("package", "main", "Go package name")
	outFlag := flag.String("o", "", "Output Go file path")
	flag.Parse()

	args := flag.Args()
	if len(args) < 1 {
		fmt.Fprintln(os.Stderr, "usage: vuic <file.vui> -o <file_vui.go> -package <pkg>")
		os.Exit(1)
	}

	srcPath := args[0]
	data, err := os.ReadFile(srcPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "vuic: failed to read %s: %v\n", srcPath, err)
		os.Exit(1)
	}

	var doc VuiDocument
	if err := json.Unmarshal(data, &doc); err != nil {
		fmt.Fprintf(os.Stderr, "vuic: failed to parse JSON in %s: %v\n", srcPath, err)
		os.Exit(1)
	}

	outPath := *outFlag
	if outPath == "" {
		base := strings.TrimSuffix(srcPath, filepath.Ext(srcPath))
		outPath = base + "_vui.go"
	}

	goCode := generateGoCode(&doc, srcPath, *pkgFlag)
	if err := os.WriteFile(outPath, []byte(goCode), 0644); err != nil {
		fmt.Fprintf(os.Stderr, "vuic: failed to write %s: %v\n", outPath, err)
		os.Exit(1)
	}

	fmt.Printf("Compiled %s -> %s\n", srcPath, outPath)
}
